ALTER TABLE fulfillment_tasks ADD COLUMN reviewer_membership_id BIGINT NULL AFTER assignee_membership_id;
ALTER TABLE fulfillment_tasks ADD CONSTRAINT fk_tasks_reviewer FOREIGN KEY (reviewer_membership_id) REFERENCES memberships(id);
CREATE TABLE evidence_submissions (id BIGINT PRIMARY KEY AUTO_INCREMENT, tenant_id BIGINT NOT NULL, task_id BIGINT NOT NULL, file_id BIGINT NOT NULL, submitter_membership_id BIGINT NOT NULL, reviewer_membership_id BIGINT NOT NULL, submit_note VARCHAR(1000) NULL, review_status VARCHAR(32) NOT NULL, review_note VARCHAR(1000) NULL, submitted_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), reviewed_at DATETIME(3) NULL, KEY idx_evidence_review(tenant_id,reviewer_membership_id,review_status), CONSTRAINT fk_es_t FOREIGN KEY(tenant_id) REFERENCES tenants(id), CONSTRAINT fk_es_task FOREIGN KEY(task_id) REFERENCES fulfillment_tasks(id), CONSTRAINT fk_es_file FOREIGN KEY(file_id) REFERENCES file_objects(id), CONSTRAINT fk_es_submit FOREIGN KEY(submitter_membership_id) REFERENCES memberships(id), CONSTRAINT fk_es_review FOREIGN KEY(reviewer_membership_id) REFERENCES memberships(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
